            w = -w;
        }

        if (h < 0) {
            y += h;
            h = -h;
        }

        if (width > w / 2 || width > h / 2) {
            width = MAX(w / 2, h / 2);
        }

        draw_round_rect(surf, x, y, x + w - 1, y + h - 1, radius, width, color,
